contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address caller, address newOwner) public {
        address ownerBefore = c.owner();
        bool isOwner = (caller == ownerBefore);
        bool reverted;
        if (isOwner) {
            c.transferOwnership(newOwner);
            reverted = false;
        } else {
            try c.transferOwnership(newOwner) { reverted = false; } catch { reverted = true; }
        }
        address ownerAfter = c.owner();
        assert(isOwner
            ? (reverted == false && ownerAfter == newOwner)
            : (reverted == true && ownerAfter == ownerBefore));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address caller, address newOwner) public {
        require(caller != address(0));
